&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de magus&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_magus_0&quot; href=&quot;#Les_arch&#233;types_de_magus_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-Occulte-(Magus).html&quot; title=&quot;Archer occulte&quot;&gt;Archer occulte&lt;/a&gt; (HOTS)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;l&#233;mentaire-(Magus).html&quot; title=&quot;Chevalier &#233;l&#233;mentaire (magus)&quot;&gt;Chevalier &#233;l&#233;mentaire&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Suli-(Race).html&quot; title=&quot;Les sulis&quot;&gt;Suli&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Danse-Sort-(Magus).html&quot; title=&quot;Danse-sort&quot;&gt;Danse-sort&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-De-La-Tour-(Magus).html&quot; title=&quot;D&#233;fenseur de la tour&quot;&gt;D&#233;fenseur de la tour&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;corcheur-Fi&#233;lon-(Magus).html&quot; title=&quot;&#201;corcheur fi&#233;lon&quot;&gt;&#201;corcheur fi&#233;lon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;sot&#233;riste-(Magus).html&quot; title=&quot;&#201;sot&#233;riste&quot;&gt;&#201;sot&#233;riste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forge&#226;me-(Magus).html&quot; title=&quot;Forge&#226;me&quot;&gt;Forge&#226;me&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kensai-(Magus).html&quot; title=&quot;Kensai&quot;&gt;Kensai&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lameli&#233;-(Magus).html&quot; title=&quot;Lameli&#233;&quot;&gt;Lameli&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesprit-(Magus).html&quot; title=&quot;Lamesprit&quot;&gt;Lamesprit&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesort-(Magus).html&quot; title=&quot;Lamesort&quot;&gt;Lamesort&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lanceur-De-Mal&#233;fices-(Magus).html&quot; title=&quot;Lanceur de mal&#233;fices&quot;&gt;Lanceur de mal&#233;fices&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mage-De-Bataille-Blind&#233;-(Magus).html&quot; title=&quot;Mage de bataille blind&#233;&quot;&gt;Mage de bataille blind&#233;&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myrmidarque-(Magus).html&quot; title=&quot;Myrmidarque&quot;&gt;Myrmidarque&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejeton-&#201;trange-(Magus).html&quot; title=&quot;Rejeton &#233;trange&quot;&gt;Rejeton &#233;trange&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Skirnir-(Magus).html&quot; title=&quot;Skirnir&quot;&gt;Skirnir&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialiste-Du-B&#226;ton-(Magus).html&quot; title=&quot;Sp&#233;cialiste du b&#226;ton&quot;&gt;Sp&#233;cialiste du b&#226;ton&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Elfe.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Elfe.ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Elfe.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;elfes&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;i&gt;Les elfes accordent tant d’importance aux magiciens que cela influe sur la mani&#232;re dont tous les elfes se per&#231;oivent, m&#234;me ceux qui n’appartiennent pas &#224; cette classe. Beaucoup de magi elfiques ne se consid&#232;rent pas comme des ma&#238;tres qui m&#234;lent escrime et magie, mais plut&#244;t comme une sous-cat&#233;gorie de magiciens qui &#233;tudient les effets des mouvements et des techniques physiques sur les incantations. Pour eux, leur capacit&#233; &#224; lancer des sorts tout en se battant est un d&#233;veloppement du concept de &#171; danse des sorts, &#187; qui n’est lui-m&#234;me qu’un autre type de magie.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_0&quot; href=&quot;#Comp&#233;tences_de_classe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un danse-sort ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (danse) &#224; sa liste de comp&#233;tences de classe et lui retire &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Danse des sorts (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Danse_des_sorts_Sur_1&quot; href=&quot;#Danse_des_sorts_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, un danse-sort peut d&#233;penser 1 point de sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RESERVEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;r&#233;serve arcanique&lt;/a&gt;, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;, pour gagner un bonus d’alt&#233;ration de +3 m (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) au d&#233;placement et un bonus d’esquive de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; qui r&#233;sultent d’un passage dans une case menac&#233;e. Cet effet dure 1 minute. Le danse-sort gagne +3 m (2 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) suppl&#233;mentaires et un bonus d&#39;esquive de +2 &#224; la CA contre les attaques d’opportunit&#233; qui d&#233;coulent de son mouvement tous les quatre niveaux apr&#232;s le premier.&lt;br /&gt;&lt;br /&gt;Au niveau 5, le danse-sort peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, utiliser l’un des sorts suivants une fois par danse des sorts : &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Vol.html&quot; title=&quot;Vol&quot;&gt;vol&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/i&gt;. Cet effet dure 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;. Au niveau 9, le danse-sort a aussi acc&#232;s &#224; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Dimensionnelle.html&quot; title=&quot;Porte dimensionnelle&quot;&gt;porte dimensionnelle&lt;/a&gt;&lt;/i&gt; et au niveau 13, il a droit &#224; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Libert&#233;-De-Mouvement.html&quot; title=&quot;Libert&#233; de mouvement&quot;&gt;libert&#233; de mouvement&lt;/a&gt;&lt;/i&gt; pendant 1d4 rounds. Ce pouvoir remplace celui qui permet au magus de d&#233;penser des points de &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RESERVEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;r&#233;serve magique&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; pour donner un bonus magique &#224; son arme pendant 1 minute.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mouvement arcanique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Mouvement_arcanique_Sur_2&quot; href=&quot;#Mouvement_arcanique_Sur_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, quand le danse-sort lance un sort de magus, il gagne un bonus de comp&#233;tence aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;, d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; &#233;gal au niveau du sort, jusqu’au d&#233;but de son prochain tour. Ce pouvoir remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#DONSUPPLEMENTAIRE&quot; title=&quot;Le magus&quot;&gt;don suppl&#233;mentaire&lt;/a&gt; que le magus re&#231;oit au niveau 5.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Danse de l’&#233;vitement (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Danse_de_l’&#233;vitement_Sur_3&quot; href=&quot;#Danse_de_l’&#233;vitement_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 7, quand le danse-sort porte une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Legeres.html&quot; title=&quot;armure l&#233;g&#232;re&quot;&gt;armure l&#233;g&#232;re&lt;/a&gt; ou ne porte pas d’armure, il gagne un bonus d’intuition de +2 &#224; la CA. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#ARMUREINTERMEDIAIRE&quot; title=&quot;Le magus&quot;&gt;armure interm&#233;diaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Danse de l’&#233;vitement sup&#233;rieure (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Danse_de_l’&#233;vitement_sup&#233;rieure_Sur_4&quot; href=&quot;#Danse_de_l’&#233;vitement_sup&#233;rieure_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 13, quand le danse-sort porte une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Legeres.html&quot; title=&quot;armure l&#233;g&#232;re&quot;&gt;armure l&#233;g&#232;re&lt;/a&gt; ou ne porte pas d’armure, son bonus d’intuition &#224; la CA passe &#224; +4. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#ARMURELOURDE&quot; title=&quot;Le magus&quot;&gt;armure lourde&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Arcanes de magus conseill&#233;es&lt;a class=&quot;headeranchor&quot; id=&quot;Arcanes_de_magus_conseill&#233;es_5&quot; href=&quot;#Arcanes_de_magus_conseill&#233;es_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les arcanes de magus qui viennent compl&#233;ter l’arch&#233;type de danse-sort : &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Assautaccelere.html&quot; title=&quot;assaut acc&#233;l&#233;r&#233;&quot;&gt;assaut acc&#233;l&#233;r&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Boucliermagique.html&quot; title=&quot;bouclier magique&quot;&gt;bouclier magique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Capearcanique.html&quot; title=&quot;cape arcanique (arcane)&quot;&gt;cape arcanique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Courteportee.html&quot; title=&quot;courte port&#233;e (arcane)&quot;&gt;courte port&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Concentre.html&quot; title=&quot;concentr&#233; (arcane)&quot;&gt;concentr&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Defendreavecprescience.html&quot; title=&quot;d&#233;fendre avec prescience&quot;&gt;d&#233;fendre avec prescience&lt;/a&gt;.
